	FOREIGN KEY(major_id) REFERENCES majors (id) ON DELETE CASCADE, 
	FOREIGN KEY(source_id) REFERENCES data_sources (id)
);

CREATE INDEX ix_employment_career ON employment_data (career_id, year);

CREATE INDEX ix_employment_city ON employment_data (city_id, year);

CREATE INDEX ix_employment_major ON employment_data (major_id, year);

